    /** Marks this invoice as sent to the client. */
    public void markSent() {
        this.status = InvoiceStatus.SENT;
    }

    /** Cancels this invoice, so it is no longer owed. */
    public void markVoid() {
        this.status = InvoiceStatus.VOID;
    }

